import {formatDate} from './model.js';
import {bankHeader} from './finance-bank-header.js';
import {amount,today,uid,validDate} from './model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rub=n=>(n/100).toLocaleString('ru-RU',{maximumFractionDigits:2})+' ₽';
const signedMoney=s=>{const v=String(s).replace(/[\s\u00a0₽]/g,'').replace(',','.');return v.startsWith('-')?-money(v.slice(1)):money(v);};
const money=s=>{const v=String(s).replace(/[\s\u00a0₽]/g,'').replace(',','.');return !v||Number(v)===0?0:amount(v);};
export function createFinanceTables({root,getData,save,getYear,getMonth,getKind,salaryFields,salaryValues,categories,getTotals,render}){
 let dirty=false,busy=false,journal=false;const isSalary=c=>salaryFields.some(x=>x[1]===c);
 const input=(value,attrs)=>`<input ${attrs} value="${esc(value)}" data-original="${esc(value)}">`;
 function toolbar(type){return `<div class="grid-toolbar"><span class="grid-status" role="status">Все изменения сохранены</span><div><button data-grid="cancel">Отменить изменения</button><button hidden data-grid="save" data-type="${type}" class="primary">Сохранить изменения</button></div></div><p class="footnote">Tab — следующее поле · Enter — подтвердить ячейку · Esc — вернуть её значение. Можно вставить диапазон из Excel; перед сохранением проверьте значения.</p><p class="error grid-error" role="alert"></p>`;}
 function salaryView(){const year=getYear(),month=getMonth(),periods=Array.from({length:12},(_,i)=>`${year}-${String(i+1).padStart(2,'0')}`).filter(p=>month==='all'||p.slice(5)===month);return `<h3>Зарплата · таблица за ${year} год</h3>${toolbar('salary')}<div class="finance-grid-wrap"><table class="finance-grid salary-grid"><thead><tr><th>Месяц</th>${salaryFields.map(([label])=>`<th>${label}, ₽</th>`).join('')}<th>Итого</th><th>ТПР</th></tr></thead><tbody>${periods.map(p=>{const values=salaryValues(p),total=values.reduce((a,b)=>a+b,0),prior=salaryValues(`${year-1}-${p.slice(5)}`).reduce((a,b)=>a+b,0);return `<tr data-period="${p}" data-prior="${prior}"><th>${new Date(p+'-01T12:00:00').toLocaleDateString('ru-RU',{month:'long'})}</th>${values.map((v,i)=>`<td>${input(v?v/100:'',`data-cell="${i}" aria-label="${p} ${salaryFields[i][0]}" inputmode="decimal"`)}</td>`).join('')}<td data-total>${rub(total)}</td><td data-growth>${prior?((total-prior)/prior*100).toFixed(1)+'%':'—'}</td></tr>`;}).join('')}</tbody><tfoot><tr><th>Итого</th>${salaryFields.map((_,i)=>`<td data-column="${i}">${rub(periods.reduce((n,p)=>n+salaryValues(p)[i],0))}</td>`).join('')}<td data-grand>${rub(periods.reduce((n,p)=>n+salaryValues(p).reduce((a,b)=>a+b,0),0))}</td><td></td></tr></tfoot></table></div>`;}
 const bankFields=['month','bank','category','amount','date','note'];
 function bankRow(x,isNew=false){const readonly=isSalary(x.category);return `<tr data-id="${esc(x.id)}" ${isNew?'data-new="true"':''} ${readonly?'data-readonly="true"':''}>${bankFields.map((k,i)=>`<td>${readonly?esc(k==='amount'?rub(x.amount):k==='date'?formatDate(x[k])||'—':x[k]||'—'):k==='category'?`<select data-field="category" data-cell="${i}" data-original="${esc(x.category)}" aria-label="Вид дохода ${esc(x.id)}">${categories.filter(c=>!isSalary(c)).map(c=>`<option ${c===x.category?'selected':''}>${esc(c)}</option>`).join('')}</select>`:input(k==='amount'?x.amount/100:x[k]||'',`data-field="${k}" data-cell="${i}" aria-label="${k} ${esc(x.id)}" ${k==='month'?'type="month"':k==='date'?'type="date"':k==='amount'?'inputmode="decimal"':''}`)}</td>`).join('')}</tr>`;}
 function journalView(){const y=getYear(),m=getMonth(),k=getKind(),rows=getData().incomes.filter(x=>x.month.startsWith(y+'-')&&(m==='all'||x.month===`${y}-${m}`)&&(k==='all'||x.category===k)).sort((a,b)=>a.month.localeCompare(b.month)||a.bank.localeCompare(b.bank,'ru'));return `<label class="fin-filter">Вид дохода<select id="fin-kind"><option value="all">Все виды</option>${categories.map(c=>`<option ${c===k?'selected':''}>${esc(c)}</option>`).join('')}</select></label><div class="row between"><h3>Поступления · таблица</h3><button data-grid="add" class="primary">＋ Строка</button></div>${toolbar('bank')}<p class="footnote">Зарплатные строки доступны для просмотра; суммы зарплаты меняйте на вкладке «Зарплата». Прибыль от продаж рассчитывается в своих разделах.</p><div class="finance-grid-wrap"><table class="finance-grid bank-grid"><thead><tr>${['Месяц учёта','Банк / источник','Вид дохода','Сумма, ₽','Дата получения','Комментарий'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>bankRow(x)).join('')}</tbody><tfoot><tr><th colspan="3">Итого поступления</th><td data-bank-total>${rub(rows.reduce((n,x)=>n+x.amount,0))}</td><td colspan="2"></td></tr></tfoot></table></div>`;}

 const fixedSources=[
  ['Т-Банк · обычные покупки','Кэшбэк'],['Т-Банк · акции','Кэшбэк'],['Т-Банк · остаток карты','Проценты'],
  ['Т-Банк · Общак','Проценты'],['Сбер · накопительный','Проценты'],['Т-Банк · Пенсия — Бабуля','Проценты'],
  ['Т-Банк · Досрочное гашение','Проценты'],['Лояльность МИР','Кэшбэк'],['Акционные вклады / дивиденды','Проценты / дивиденды'],
  ['ВТБ','Кэшбэк / проценты'],['Альфа-Банк','Кэшбэк / проценты'],['OZON','Кэшбэк / проценты'],['Другие банки','Кэшбэк / проценты'],['Дивиденды','Дивиденды'],['Спасибо Сбер','Баллы']
 ];
 const sourceKey=(bank,category)=>JSON.stringify([bank,category]);
 function sources(){const result=fixedSources.map(([bank,category])=>({bank,category,key:sourceKey(bank,category)})),keys=new Set(result.map(x=>x.key));
  for(const x of getData().incomes){if(isSalary(x.category))continue;const key=sourceKey(x.bank,x.category);if(!keys.has(key)){keys.add(key);result.push({bank:x.bank,category:x.category,key});}}
  return result.map(x=>{const meta=(getData().incomeSources||[]).find(m=>m.key===x.key);return {...x,name:meta?.name||(x.bank==='Акционные вклады / дивиденды'?'Акционные вклады':x.bank),group:meta?.group||(x.category==='Дивиденды'?'dividends':x.category==='Баллы'||x.category.includes('Кэшбэк')?'cashback':x.category.includes('Проценты')?'deposits':'other')};}).sort((a,b)=>['cashback','deposits','dividends','other'].indexOf(a.group)-['cashback','deposits','dividends','other'].indexOf(b.group));
 }
 const sourceTotal=(period,source)=>source.bank==='Спасибо Сбер'?(getData().bonuses||[]).filter(x=>x.month===period).reduce((n,x)=>n+x.amount,0):getData().incomes.filter(x=>x.month===period&&x.bank===source.bank&&x.category===source.category).reduce((n,x)=>n+x.amount,0);
 const sourceDates=(period,c)=>[...new Set(getData().incomes.filter(x=>x.month===period&&x.bank===c.bank&&x.category===c.category&&x.date).map(x=>x.date))];
 const sourceDate=(period,c)=>sourceDates(period,c).length===1?sourceDates(period,c)[0]:'';
 function configureSources(){const cols=sources(),modal=document.getElementById('modal');modal.innerHTML=`<div class="modal-header"><h2>Настроить источники</h2><button data-close>✕</button></div><form class="modal-body">${cols.map((c,i)=>`<label class="field">Название<input name="name-${i}" value="${esc(c.name)}" required maxlength="100"></label><label class="field">Группа<select name="group-${i}">${[['cashback','Кэшбэки'],['deposits','Вклады'],['dividends','Дивиденды'],['other','Прочее']].map(([k,l])=>`<option value="${k}" ${c.group===k?'selected':''}>${l}</option>`).join('')}</select></label>`).join('')}<p class="error"></p><button type="submit" class="primary">Сохранить</button></form>`;modal.showModal();modal.querySelector('[data-close]').onclick=()=>modal.close();modal.querySelector('form').onsubmit=async e=>{e.preventDefault();const before=structuredClone(getData().incomeSources),f=new FormData(e.target);getData().incomeSources=cols.map((c,i)=>({key:c.key,name:f.get('name-'+i).trim(),group:f.get('group-'+i)}));try{await save();modal.close();render();}catch(err){getData().incomeSources=before;modal.querySelector('.error').textContent=err.message;}};}
 function monthlyView(){const y=getYear(),m=getMonth(),cols=sources(),periods=Array.from({length:12},(_,i)=>`${y}-${String(i+1).padStart(2,'0')}`).filter(p=>m==='all'||p.slice(5)===m),totals=cols.map(()=>0),computed=[0,0,0,0];
  return `<div class="row between"><h3>Доходы по месяцам · ${y}</h3><button data-grid="sources" class="secondary">Настроить источники</button></div>${toolbar('monthly')}<p class="footnote">Введите итог каждого источника за месяц. Можно довносить и исправлять суммы. Зарплата, визитки и продажи заполняются в своих разделах; здесь их итоги обновляются автоматически.</p><p class="footnote">Столбцы одинаковы для всех годов. Отдельные поступления и даты доступны в «Истории поступлений»; изменение месячного итога сохраняется отдельной корректировкой.</p><div class="finance-grid-wrap"><table class="finance-grid monthly-grid"><thead><tr><th rowspan="3">Месяц</th>${[['cashback','Кэшбэки'],['deposits','Вклады'],['dividends','Дивиденды'],['other','Прочее']].filter(([k])=>cols.some(c=>c.group===k)).map(([k,l])=>`<th colspan="${cols.filter(c=>c.group===k).length*2}" class="income-group">${l}</th>`).join('')}<th rowspan="3">Зарплата</th><th rowspan="3">Визитки · прибыль</th><th rowspan="3">Продажи · прибыль</th><th rowspan="3">Всего</th></tr><tr>${cols.map(c=>`<th colspan="2" class="bank-header-cell">${bankHeader(c.name)}</th>`).join('')}</tr><tr>${cols.map(c=>`<th>${c.category==='Баллы'?'Баллы':'Сумма, ₽'}</th><th>Дата поступления</th>`).join('')}</tr></thead><tbody>${periods.map(period=>{const t=getTotals(period),derived=[t.salary,t.sales.filter(x=>x.card).reduce((n,x)=>n+x.received-x.cost,0),t.sales.filter(x=>!x.card).reduce((n,x)=>n+x.received-x.cost,0)],values=cols.map(c=>sourceTotal(period,c)),total=values.reduce((n,v,i)=>n+(cols[i].category==='Баллы'?0:v),0)+derived.reduce((n,v)=>n+v,0);values.forEach((v,i)=>totals[i]+=v);[...derived,total].forEach((v,i)=>computed[i]+=v);return `<tr data-period="${period}" data-derived="${derived.reduce((n,v)=>n+v,0)}"><th>${new Date(period+'-01T12:00:00').toLocaleDateString('ru-RU',{month:'long'})}</th>${values.map((v,i)=>`<td>${input(v?v/100:'',`data-cell="${i*2}" data-kind="${cols[i].category==='Баллы'?'points':'amount'}" ${cols[i].category==='Баллы'?'disabled':''} data-source="${esc(cols[i].key)}" aria-label="${period} ${esc(cols[i].bank)} ${esc(cols[i].category)}" inputmode="decimal"`)}</td><td>${input(sourceDate(period,cols[i]),`data-cell="${i*2+1}" data-kind="date" data-source="${esc(cols[i].key)}" type="date" aria-label="${period} ${esc(cols[i].name)} дата" ${cols[i].category==='Баллы'||sourceDates(period,cols[i]).length>1?'disabled title="Несколько дат — смотрите историю поступлений"':''}`)}</td>`).join('')}${derived.map(v=>`<td class="monthly-computed">${rub(v)}</td>`).join('')}<td data-monthly-total class="monthly-computed">${rub(total)}</td></tr>`;}).join('')}</tbody><tfoot><tr><th>Итого</th>${totals.map((v,i)=>`<td data-monthly-column="${i}">${cols[i].category==='Баллы'?(v/100).toLocaleString('ru-RU')+' баллов':rub(v)}</td><td></td>`).join('')}${computed.slice(0,3).map(v=>`<td>${rub(v)}</td>`).join('')}<td data-monthly-grand>${rub(computed[3])}</td></tr></tfoot></table></div>`;
 }
 function incomesView(){return `<div class="fin-view-toggle ledger-section-nav"><button data-grid="monthly-mode" class="${journal?'':'selected'}">По месяцам</button><button data-grid="journal-mode" class="${journal?'selected':''}">История поступлений</button></div>`+(journal?journalView():monthlyView());}
 function applyMonthly(){const dateChanges=[];root.querySelectorAll('.monthly-grid tbody tr').forEach(r=>r.querySelectorAll('[data-kind="date"]:not(:disabled)').forEach(e=>{if(e.value===e.dataset.original)return;if(e.value&&!validDate(e.value))throw Error('Проверьте дату поступления.');dateChanges.push({period:r.dataset.period,key:e.dataset.source,date:e.value});}));const staged=[];root.querySelectorAll('.monthly-grid tbody tr').forEach(row=>row.querySelectorAll('input[data-kind="amount"]').forEach(e=>{const value=money(e.value),[bank,category]=JSON.parse(e.dataset.source),period=row.dataset.period;if(!/^20\d\d-(0[1-9]|1[0-2])$/.test(period)||!categories.includes(category)||isSalary(category))throw Error('Проверьте источник и месяц.');const delta=value-sourceTotal(period,{bank,category});if(delta)staged.push({bank,category,period,delta});}));
  for(const {bank,category,period,delta} of staged){const data=getData(),existing=data.incomes.find(x=>x.monthlyAdjustment&&x.bank===bank&&x.category===category&&x.month===period);if(existing)existing.amount+=delta;else data.incomes.push({id:uid(),bank,category,month:period,amount:delta,date:'',note:'Корректировка месячного итога',monthlyAdjustment:true});}for(const c of dateChanges){const [bank,category]=JSON.parse(c.key),rows=getData().incomes.filter(x=>x.month===c.period&&x.bank===bank&&x.category===category),target=rows.find(x=>!x.monthlyAdjustment)||rows[0];if(target)target.date=c.date;else if(c.date)getData().incomes.push({id:uid(),bank,category,month:c.period,amount:0,date:c.date,note:'',monthlyAdjustment:true});}
 }
 function updateMonthly(){const rows=root.querySelectorAll('.monthly-grid tbody tr');if(!rows.length)return;const cols=Array.from(root.querySelectorAll('[data-monthly-column]'),()=>0);let grand=0;for(const row of rows){try{let total=Number(row.dataset.derived);row.querySelectorAll('input[data-kind="amount"],input[data-kind="points"]').forEach((e,i)=>{const n=money(e.value);cols[i]+=n;if(e.dataset.kind!=='points')total+=n;});row.querySelector('[data-monthly-total]').textContent=rub(total);grand+=total;}catch{row.querySelector('[data-monthly-total]').textContent='Проверьте сумму';}}
  cols.forEach((v,i)=>root.querySelector(`[data-monthly-column="${i}"]`).textContent=sources()[i].category==='Баллы'?(v/100).toLocaleString('ru-RU')+' баллов':rub(v));root.querySelector('[data-monthly-grand]').textContent=rub(grand);
 }

 let autoTimer;
 function setDirty(){dirty=true;clearTimeout(autoTimer);autoTimer=setTimeout(autoSave,650);const s=root.querySelector('.grid-status');if(s)s.textContent='Есть несохранённые изменения';}
 function update(){updateMonthly();const rows=root.querySelectorAll('.salary-grid tbody tr');let grand=0,columns=[0,0,0,0,0];for(const row of rows){let total=0;try{row.querySelectorAll('input').forEach((e,i)=>{const n=money(e.value);total+=n;columns[i]+=n;});row.querySelector('[data-total]').textContent=rub(total);const prior=Number(row.dataset.prior);row.querySelector('[data-growth]').textContent=prior?((total-prior)/prior*100).toFixed(1)+'%':'—';grand+=total;}catch{row.querySelector('[data-total]').textContent='Проверьте сумму';}}if(rows.length){root.querySelector('[data-grand]').textContent=rub(grand);columns.forEach((n,i)=>root.querySelector(`[data-column="${i}"]`).textContent=rub(n));}const out=root.querySelector('[data-bank-total]');if(out){let total=0;try{root.querySelectorAll('.bank-grid tbody tr').forEach(row=>{total+=row.dataset.readonly?getData().incomes.find(x=>x.id===row.dataset.id).amount:(getData().incomes.find(x=>x.id===row.dataset.id)?.monthlyAdjustment?signedMoney:money)(row.querySelector('[data-field="amount"]').value);});out.textContent=rub(total);}catch{out.textContent='Проверьте сумму';}}}
 function applySalary(){const changes=[];root.querySelectorAll('.salary-grid tbody tr').forEach(row=>{const values=[...row.querySelectorAll('input')].map(e=>money(e.value));changes.push([row.dataset.period,values]);});for(const [period,values]of changes){const current=salaryValues(period);values.forEach((value,i)=>{const delta=value-current[i];if(!delta)return;const data=getData(),category=salaryFields[i][1],existing=data.incomes.find(x=>x.salaryAdjustment&&x.category===category&&x.month===period);if(existing){existing.amount+=delta;existing.date=today();}else data.incomes.push({id:uid(),category,amount:delta,date:today(),month:period,bank:'Сводный ввод зарплаты',note:'Из таблицы зарплаты',salaryAdjustment:true});});}}
 function applyBank(){const records=[];root.querySelectorAll('.bank-grid tbody tr:not([data-readonly])').forEach(row=>{const record={id:row.dataset.id};bankFields.forEach(k=>record[k]=row.querySelector(`[data-field="${k}"]`).value.trim());record.amount=getData().incomes.find(x=>x.id===record.id)?.monthlyAdjustment?signedMoney(record.amount):money(record.amount);if(!/^20\d\d-(0[1-9]|1[0-2])$/.test(record.month)||!record.bank||record.bank.length>100||record.note.length>500||record.date&&!validDate(record.date)||!categories.includes(record.category)||isSalary(record.category))throw Error('Проверьте месяц, банк, категорию и дату поступления.');records.push(record);});for(const record of records){const old=getData().incomes.find(x=>x.id===record.id);if(old)Object.assign(old,record);else getData().incomes.push(record);}}
 async function autoSave(){if(!dirty)return;if(busy){autoTimer=setTimeout(autoSave,250);return;}busy=true;const snapshots=[...root.querySelectorAll('.salary-grid [data-original],.monthly-grid [data-original],.bank-grid [data-original]')].map(e=>[e,e.value]),status=root.querySelector('.grid-status');if(status)status.textContent='Сохраняется…';try{if(root.querySelector('.salary-grid'))applySalary();else if(root.querySelector('.monthly-grid'))applyMonthly();else applyBank();await save(); snapshots.forEach(([e,v])=>{e.dataset.original=v;e.closest('[data-new]')?.removeAttribute('data-new');});dirty=snapshots.some(([e,v])=>e.value!==v);root.querySelector('.grid-error').textContent='';if(status)status.textContent=dirty?'Сохраняется…':'Все изменения сохранены';if(dirty)autoTimer=setTimeout(autoSave,250);}catch(err){dirty=true;root.querySelector('.grid-error').textContent=err.message;if(status)status.textContent='Не сохранено';}finally{busy=false;}}
 root.addEventListener('input',e=>{if(!e.target.closest('.salary-grid,.bank-grid,.monthly-grid'))return;setDirty();update();});root.addEventListener('change',e=>{if(e.target.closest('.salary-grid,.bank-grid,.monthly-grid')&&e.target.value!==e.target.dataset.original){setDirty();update();}});
 root.addEventListener('keydown',e=>{if(!e.target.matches('.salary-grid input,.bank-grid input,.bank-grid select,.monthly-grid input'))return;if(e.key==='Escape'){e.target.value=e.target.dataset.original;setDirty();update();}if(e.key==='Enter'){e.preventDefault();e.target.blur();}});
 root.addEventListener('paste',e=>{const cell=e.target.closest('.salary-grid [data-cell],.bank-grid [data-cell],.monthly-grid [data-cell]');if(!cell)return;const text=e.clipboardData.getData('text/plain');if(!/[\t\r\n]/.test(text))return;e.preventDefault();const rows=[...cell.closest('tbody').querySelectorAll('tr')],startRow=rows.indexOf(cell.closest('tr')),startCol=Number(cell.dataset.cell),matrix=text.trimEnd().split(/\r?\n/).map(s=>s.split('\t'));if(startRow+matrix.length>rows.length){root.querySelector('.grid-error').textContent='Недостаточно строк. Добавьте строки или уменьшите диапазон.';return;}const staged=[];for(let i=0;i<matrix.length;i++)for(let j=0;j<matrix[i].length;j++){const target=rows[startRow+i].querySelector(`[data-cell="${startCol+j}"]`);if(!target){root.querySelector('.grid-error').textContent='Вставляйте только диапазон полей ввода, без итогов и заголовков.';return;}let value=matrix[i][j].trim();if(target.matches('select')&&![...target.options].some(o=>o.value===value)){root.querySelector('.grid-error').textContent='Категория в Excel не совпадает с категориями приложения.';return;}if(target.type==='date'&&/^\d{2}\.\d{2}\.\d{4}$/.test(value))value=value.split('.').reverse().join('-');staged.push([target,value]);}staged.forEach(([target,value])=>target.value=value);setDirty();update();root.querySelector('.grid-error').textContent='';});
 root.addEventListener('click',async e=>{const b=e.target.closest('[data-grid]');if(!b||busy)return;const action=b.dataset.grid;if(action==='sources'){if(dirty){root.querySelector('.grid-error').textContent='Дождитесь автосохранения.';return;}configureSources();return;}if(action==='monthly-mode'||action==='journal-mode'){if(dirty){root.querySelector('.grid-error').textContent='Дождитесь автосохранения или исправьте поле с ошибкой.';return;}journal=action==='journal-mode';render();return;}if(action==='add'){const tbody=root.querySelector('.bank-grid tbody'),m=getMonth(),y=getYear();tbody.insertAdjacentHTML('afterbegin',bankRow({id:uid(),month:`${y}-${m==='all'?today().slice(5,7):m}`,bank:'',category:'Кэшбэк',amount:0,date:today(),note:''},true));setDirty();tbody.closest('.finance-grid-wrap').scrollTop=0;tbody.firstElementChild.querySelector('[data-field="bank"]').focus();return;}if(action==='cancel'){root.querySelectorAll('.finance-grid [data-original]').forEach(x=>x.value=x.dataset.original);root.querySelectorAll('[data-new]').forEach(x=>x.remove());dirty=false;update();root.querySelector('.grid-status').textContent='Изменения отменены';root.querySelector('.grid-error').textContent='';return;}if(action==='save'){busy=true;b.disabled=true;const error=root.querySelector('.grid-error');try{if(b.dataset.type==='salary')applySalary();else if(b.dataset.type==='monthly')applyMonthly();else applyBank();await save();dirty=false;}catch(err){error.textContent=err.message;root.querySelector('.grid-status').textContent='Не сохранено. Проверьте данные или обновите страницу.';}finally{busy=false;b.disabled=false;}}});
 return {salaryView,incomesView,getSources:sources,hasDirty:()=>dirty};
}
